import type {
  DepthDiffEvent,
  DepthSnapshot,
  OrderBookSnapshotView,
  OrderBookStatus,
  PriceLevel,
} from '../types';

/**
 * Maintains a single symbol's local order book in sync with Binance's
 * partial-book depth diff stream, following Binance's documented
 * "how to manage a local order book" procedure:
 *
 *  1. Buffer diff events while no snapshot has been applied yet.
 *  2. On snapshot: discard buffered events with `u <= lastUpdateId`. The
 *     first remaining event must satisfy `U <= lastUpdateId + 1 <= u`.
 *  3. Apply events in order as long as each event's `U === previous.u + 1`.
 *  4. If a gap is ever detected, mark the book `stale` and surface
 *     `needsResync() === true` without corrupting previously-applied state;
 *     the caller is expected to re-fetch a REST snapshot and call
 *     `applySnapshot` again.
 *
 * Implementation is intentionally framework-agnostic (no network, no DOM)
 * so it can be unit tested in isolation and reused inside the SharedWorker.
 */
export class OrderBookManager {
  constructor(public readonly symbol: string) {
    throw new Error('not implemented');
  }

  get status(): OrderBookStatus {
    throw new Error('not implemented');
  }

  /** Buffer or apply a diff event depending on current sync state. */
  applyDiff(_evt: DepthDiffEvent): void {
    throw new Error('not implemented');
  }

  /** Apply a REST snapshot and replay/validate buffered diffs against it. */
  applySnapshot(_snapshot: DepthSnapshot): void {
    throw new Error('not implemented');
  }

  /** True when the manager has detected a sequence gap and needs a fresh REST snapshot. */
  needsResync(): boolean {
    throw new Error('not implemented');
  }

  getView(): OrderBookSnapshotView {
    throw new Error('not implemented');
  }

  getTopN(_n: number): { bids: PriceLevel[]; asks: PriceLevel[] } {
    throw new Error('not implemented');
  }
}

import { describe, it, expect } from 'vitest';
import { OrderBookManager } from './OrderBookManager';
import type { DepthDiffEvent, DepthSnapshot } from '../types';

function diff(U: number, u: number, b: [string, string][] = [], a: [string, string][] = [], E = u): DepthDiffEvent {
  return { e: 'depthUpdate', E, s: 'BTCUSDT', U, u, b, a };
}

function snapshot(lastUpdateId: number, bids: [string, string][], asks: [string, string][]): DepthSnapshot {
  return { lastUpdateId, bids, asks };
}

describe('OrderBookManager', () => {
  it('starts uninitialized with an empty book', () => {
    const m = new OrderBookManager('BTCUSDT');
    expect(m.status).toBe('uninitialized');
    const view = m.getView();
    expect(view.bids).toEqual([]);
    expect(view.asks).toEqual([]);
    expect(view.bestBid).toBeNull();
    expect(view.bestAsk).toBeNull();
  });

  it('buffers diffs received before any snapshot without throwing or going live', () => {
    const m = new OrderBookManager('BTCUSDT');
    expect(() => m.applyDiff(diff(100, 105))).not.toThrow();
    expect(m.status).not.toBe('live');
  });

  it('goes live from a snapshot with no prior buffered diffs', () => {
    const m = new OrderBookManager('BTCUSDT');
    m.applySnapshot(snapshot(1000, [['100.00', '1.5']], [['101.00', '2.0']]));
    expect(m.status).toBe('live');
    const view = m.getView();
    expect(view.lastUpdateId).toBe(1000);
    expect(view.bestBid).toEqual({ price: 100, qty: 1.5 });
    expect(view.bestAsk).toEqual({ price: 101, qty: 2.0 });
  });

  it('discards buffered diffs older than the snapshot and applies the straddling + contiguous ones', () => {
    const m = new OrderBookManager('BTCUSDT');
    // stale, fully before snapshot -> discarded
    m.applyDiff(diff(900, 950));
    // straddles lastUpdateId (1000): U <= 1001 <= u
    m.applyDiff(diff(990, 1005, [['100.00', '3.0']]));
    // contiguous follow-up
    m.applyDiff(diff(1006, 1010, [['100.00', '2.0']]));

    m.applySnapshot(snapshot(1000, [['100.00', '1.5']], [['101.00', '2.0']]));

    expect(m.status).toBe('live');
    expect(m.needsResync()).toBe(false);
    const view = m.getView();
    expect(view.lastUpdateId).toBe(1010);
    expect(view.bestBid).toEqual({ price: 100, qty: 2.0 });
  });

  it('flags needsResync when buffered diffs have a gap right after the snapshot, but keeps the snapshot visible', () => {
    const m = new OrderBookManager('BTCUSDT');
    // Gap: this event's U (1010) is way past lastUpdateId+1 (1001)
    m.applyDiff(diff(1010, 1020, [['100.00', '9.0']]));
    m.applySnapshot(snapshot(1000, [['100.00', '1.5']], [['101.00', '2.0']]));

    expect(m.needsResync()).toBe(true);
    expect(m.status).toBe('stale');
    // Book must not be blank/corrupted - traders should still see the last known-good state.
    const view = m.getView();
    expect(view.bestBid).toEqual({ price: 100, qty: 1.5 });
  });

  it('ignores diffs whose final update id is at or before the current lastUpdateId (duplicates/old)', () => {
    const m = new OrderBookManager('BTCUSDT');
    m.applySnapshot(snapshot(1000, [['100.00', '1.5']], [['101.00', '2.0']]));
    m.applyDiff(diff(900, 999, [['100.00', '999']])); // u <= 1000 -> ignored entirely
    const view = m.getView();
    expect(view.lastUpdateId).toBe(1000);
    expect(view.bestBid).toEqual({ price: 100, qty: 1.5 });
  });

  it('applies a contiguous live diff, updating and removing levels', () => {
    const m = new OrderBookManager('BTCUSDT');
    m.applySnapshot(snapshot(1000, [['100.00', '1.5'], ['99.50', '1.0']], [['101.00', '2.0']]));
    m.applyDiff(diff(1001, 1001, [['100.00', '0.00000000'], ['99.00', '5.0']], [['101.00', '3.0']]));

    const view = m.getView();
    expect(view.lastUpdateId).toBe(1001);
    // 100.00 removed (qty 0), 99.00 added
    expect(view.bids.map((l) => l.price)).toEqual([99.5, 99]);
    expect(view.bestAsk).toEqual({ price: 101, qty: 3.0 });
  });

  it('detects a mid-stream gap, marks stale, and does not corrupt the book with the gapped event', () => {
    const m = new OrderBookManager('BTCUSDT');
    m.applySnapshot(snapshot(1000, [['100.00', '1.5']], [['101.00', '2.0']]));
    // U should be 1001 to be contiguous; 1005 is a gap
    m.applyDiff(diff(1005, 1010, [['100.00', '999']]));

    expect(m.status).toBe('stale');
    expect(m.needsResync()).toBe(true);
    const view = m.getView();
    expect(view.lastUpdateId).toBe(1000); // not advanced
    expect(view.bestBid).toEqual({ price: 100, qty: 1.5 }); // not corrupted by the gapped event
  });

  it('recovers from stale back to live after a fresh snapshot is applied', () => {
    const m = new OrderBookManager('BTCUSDT');
    m.applySnapshot(snapshot(1000, [['100.00', '1.5']], [['101.00', '2.0']]));
    m.applyDiff(diff(1005, 1010, [['100.00', '999']])); // induces gap -> stale
    expect(m.status).toBe('stale');

    m.applySnapshot(snapshot(2000, [['105.00', '4.0']], [['106.00', '1.0']]));
    expect(m.status).toBe('live');
    expect(m.needsResync()).toBe(false);
    expect(m.getView().lastUpdateId).toBe(2000);
  });

  it('keeps bids sorted descending and asks ascending regardless of update order', () => {
    const m = new OrderBookManager('BTCUSDT');
    m.applySnapshot(
      snapshot(
        1,
        [['100.00', '1'], ['102.00', '1'], ['101.00', '1']],
        [['110.00', '1'], ['108.00', '1'], ['109.00', '1']],
      ),
    );
    const view = m.getView();
    expect(view.bids.map((l) => l.price)).toEqual([102, 101, 100]);
    expect(view.asks.map((l) => l.price)).toEqual([108, 109, 110]);
  });

  it('computes spread as bestAsk - bestBid, and null when either side is empty', () => {
    const m = new OrderBookManager('BTCUSDT');
    m.applySnapshot(snapshot(1, [['100.00', '1']], [['101.00', '1']]));
    expect(m.getView().spread).toBeCloseTo(1, 10);

    const empty = new OrderBookManager('ETHUSDT');
    empty.applySnapshot(snapshot(1, [], []));
    expect(empty.getView().spread).toBeNull();
    expect(empty.getView().bestBid).toBeNull();
  });

  it('getTopN returns at most N levels per side, preserving sort order', () => {
    const m = new OrderBookManager('BTCUSDT');
    const bids: [string, string][] = Array.from({ length: 10 }, (_, i) => [`${100 - i}.00`, '1']);
    const asks: [string, string][] = Array.from({ length: 10 }, (_, i) => [`${101 + i}.00`, '1']);
    m.applySnapshot(snapshot(1, bids, asks));
    const top = m.getTopN(3);
    expect(top.bids.map((l) => l.price)).toEqual([100, 99, 98]);
    expect(top.asks.map((l) => l.price)).toEqual([101, 102, 103]);
  });

  it('a qty of exactly "0" removes a previously-known ask level', () => {
    const m = new OrderBookManager('BTCUSDT');
    m.applySnapshot(snapshot(1, [['100.00', '1']], [['101.00', '1'], ['102.00', '1']]));
    m.applyDiff(diff(2, 2, [], [['101.00', '0']]));
    expect(m.getView().asks.map((l) => l.price)).toEqual([102]);
  });
});

export interface SubscribeFrame {
  method: 'SUBSCRIBE' | 'UNSUBSCRIBE';
  params: string[];
  id: number;
}

export interface SubscriptionManagerOptions {
  /** Binance caps outbound control messages at 5/sec per connection. */
  maxMessagesPerSecond?: number;
  /** Binance caps a single connection at 1024 streams. */
  maxStreamsPerConnection?: number;
  now?: () => number;
}

/**
 * Tracks which streams are needed (ref-counted across many panel "owners"),
 * batches SUBSCRIBE/UNSUBSCRIBE frames to minimize message count, and
 * throttles outgoing frames to stay within Binance's rate limit.
 */
export class SubscriptionManager {
  constructor(_opts?: SubscriptionManagerOptions) {
    throw new Error('not implemented');
  }

  /** Returns false (and does nothing) if accepting a brand-new stream would exceed capacity. */
  subscribe(_ownerId: string, _stream: string): boolean {
    throw new Error('not implemented');
  }

  unsubscribe(_ownerId: string, _stream: string): void {
    throw new Error('not implemented');
  }

  get activeStreamCount(): number {
    throw new Error('not implemented');
  }

  get pendingCount(): number {
    throw new Error('not implemented');
  }

  isAtCapacity(): boolean {
    throw new Error('not implemented');
  }

  /** Attempt to flush queued frames, respecting the rolling-window rate limit. Returns the frames actually sent. */
  flush(): SubscribeFrame[] {
    throw new Error('not implemented');
  }
}

import { describe, it, expect, vi } from 'vitest';
import { SubscriptionManager } from './SubscriptionManager';

describe('SubscriptionManager', () => {
  it('sends one SUBSCRIBE frame for a brand-new stream on flush', () => {
    const sm = new SubscriptionManager();
    sm.subscribe('panel-1', 'btcusdt@depth@100ms');
    const sent = sm.flush();
    expect(sent).toHaveLength(1);
    expect(sent[0]).toMatchObject({ method: 'SUBSCRIBE', params: ['btcusdt@depth@100ms'] });
  });

  it('does not re-subscribe on the wire when a second owner wants an already-active stream', () => {
    const sm = new SubscriptionManager();
    sm.subscribe('panel-1', 'btcusdt@depth@100ms');
    sm.flush();
    sm.subscribe('panel-2', 'btcusdt@depth@100ms');
    expect(sm.flush()).toHaveLength(0);
    expect(sm.activeStreamCount).toBe(1);
  });

  it('keeps a stream alive while any owner still references it', () => {
    const sm = new SubscriptionManager();
    sm.subscribe('panel-1', 'btcusdt@depth@100ms');
    sm.subscribe('panel-2', 'btcusdt@depth@100ms');
    sm.flush();
    sm.unsubscribe('panel-1', 'btcusdt@depth@100ms');
    expect(sm.flush()).toHaveLength(0);
    expect(sm.activeStreamCount).toBe(1);
  });

  it('unsubscribes on the wire once the last owner releases a stream', () => {
    const sm = new SubscriptionManager();
    sm.subscribe('panel-1', 'btcusdt@depth@100ms');
    sm.flush();
    sm.unsubscribe('panel-1', 'btcusdt@depth@100ms');
    const sent = sm.flush();
    expect(sent).toHaveLength(1);
    expect(sent[0]).toMatchObject({ method: 'UNSUBSCRIBE', params: ['btcusdt@depth@100ms'] });
    expect(sm.activeStreamCount).toBe(0);
  });

  it('batches multiple new streams requested before a flush into a single SUBSCRIBE frame', () => {
    const sm = new SubscriptionManager();
    sm.subscribe('p1', 'btcusdt@depth@100ms');
    sm.subscribe('p2', 'ethusdt@depth@100ms');
    sm.subscribe('p3', 'btcusdt@aggTrade');
    const sent = sm.flush();
    expect(sent).toHaveLength(1);
    expect(sent[0].params.sort()).toEqual(
      ['btcusdt@aggTrade', 'btcusdt@depth@100ms', 'ethusdt@depth@100ms'].sort(),
    );
  });

  it('throttles frames to the configured messages-per-second budget, deferring the rest', () => {
    let t = 0;
    const sm = new SubscriptionManager({ maxMessagesPerSecond: 1, now: () => t });
    sm.subscribe('p1', 'btcusdt@depth@100ms');
    sm.flush(); // consumes the 1 allowed message in this window
    sm.unsubscribe('p1', 'btcusdt@depth@100ms'); // queues an UNSUBSCRIBE
    sm.subscribe('p2', 'ethusdt@depth@100ms'); // queues a SUBSCRIBE

    // Still within the same 1s window -> rate limit blocks further sends.
    expect(sm.flush()).toHaveLength(0);

    // Advance past the window -> queued frames can now go out.
    t += 1001;
    const sent = sm.flush();
    expect(sent.length).toBeGreaterThan(0);
  });

  it('rejects subscribing to a brand-new stream once at capacity, without affecting existing streams', () => {
    const sm = new SubscriptionManager({ maxStreamsPerConnection: 2 });
    expect(sm.subscribe('p1', 'a@depth@100ms')).toBe(true);
    expect(sm.subscribe('p2', 'b@depth@100ms')).toBe(true);
    expect(sm.isAtCapacity()).toBe(true);
    expect(sm.subscribe('p3', 'c@depth@100ms')).toBe(false);
    expect(sm.activeStreamCount).toBe(2);
  });

  it('still allows a second owner to join an already-active stream even at capacity', () => {
    const sm = new SubscriptionManager({ maxStreamsPerConnection: 1 });
    expect(sm.subscribe('p1', 'a@depth@100ms')).toBe(true);
    expect(sm.subscribe('p2', 'a@depth@100ms')).toBe(true);
    expect(sm.activeStreamCount).toBe(1);
  });

  it('is idempotent for duplicate subscribe calls from the same owner on the same stream', () => {
    const sm = new SubscriptionManager();
    sm.subscribe('p1', 'a@depth@100ms');
    sm.subscribe('p1', 'a@depth@100ms');
    sm.flush();
    sm.unsubscribe('p1', 'a@depth@100ms');
    const sent = sm.flush();
    expect(sent).toHaveLength(1);
    expect(sm.activeStreamCount).toBe(0);
  });
});

export type Host = 'primary' | 'fallback';

export interface ReconnectPolicyOptions {
  baseDelayMs?: number;
